"""Wallet request/response types."""

from __future__ import annotations

from enum import StrEnum
from typing import Annotated, Literal

from pydantic import BaseModel, Field


class WalletAutoReloadState(StrEnum):
    """Auto-reload configuration state."""

    UNCONFIGURED = "unconfigured"
    ON = "on"
    OFF = "off"
    PAUSED_PAYMENT_FAILED = "paused_payment_failed"
    NEEDS_PAYMENT_METHOD = "needs_payment_method"


class WalletAutoReloadUnconfigured(BaseModel):
    """Auto-reload has never been configured for this wallet."""

    state: Literal[WalletAutoReloadState.UNCONFIGURED] = Field(..., description="Current auto-reload state")


class WalletAutoReloadConfigured(BaseModel):
    """Auto-reload is configured — threshold and recharge_to are always present."""

    state: Literal[
        WalletAutoReloadState.ON,
        WalletAutoReloadState.OFF,
        WalletAutoReloadState.PAUSED_PAYMENT_FAILED,
        WalletAutoReloadState.NEEDS_PAYMENT_METHOD,
    ] = Field(..., description="Current auto-reload state")
    threshold: str = Field(..., description="Balance floor that triggers a reload.")
    recharge_to: str = Field(..., description="Balance the wallet is topped up to when a reload triggers.")


WalletAutoReload = Annotated[
    WalletAutoReloadUnconfigured | WalletAutoReloadConfigured,
    Field(discriminator="state"),
]


class WalletMeter(BaseModel):
    """One priced product on the caller's rate contract."""

    label: str = Field(..., description="Human-readable meter label")
    unit_amount: str = Field(..., description="Per-unit rate, decimal string")
    currency: str = Field(..., description="ISO 4217 currency code, e.g. USD")
    per: str | None = Field(None, description="Billable unit this meter charges per. Absent when unlabeled.")


class WalletRates(BaseModel):
    """Every priced product on the caller's rate contract, read live."""

    meters: list[WalletMeter] = Field(..., description="Priced products on the contract")
    as_of: str = Field(..., description="ISO timestamp the rates were read")


class WalletPendingTopUp(BaseModel):
    """An in-flight top-up. Completed, failed, and no-attempt states read null."""

    amount: str = Field(..., description="Top-up amount, decimal string")
    started_at: str = Field(..., description="ISO timestamp the top-up started")


class WalletResponse(BaseModel):
    """Wallet balance, auto-reload, per-product rates, and any in-flight top-up."""

    available_balance: str = Field(
        ..., description="Current spendable balance. A negative value means the wallet is overdrawn."
    )
    currency: str = Field(..., description="ISO 4217 currency code, e.g. USD")
    as_of: str = Field(..., description="ISO timestamp when the wallet was read")
    auto_reload: WalletAutoReload | None = Field(
        None, description="None means the auto-reload read failed, not that it is unconfigured"
    )
    pending_top_up: WalletPendingTopUp | None = Field(
        None, description="None means no in-flight top-up, or the ledger read failed"
    )
    rates: WalletRates | None = Field(
        None, description="None means the rates read failed, or the wallet has no rate contract yet"
    )
